/**
 * Whether the internal input is required.
 *
 * @type {boolean}
 */
get required() {
  return this.#input?.required ?? this.hasAttribute("required");
}

set required(isRequired) {
  this.toggleAttribute("required", isRequired);
  if (this.#input) {
    this.#input.required = isRequired;
  }
}
